(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.2)*20+Math.cos(y*0.012-t*0.15)*15;
  const w1y = Math.cos(y*0.015-t*0.18)*20+Math.sin(x*0.013+t*0.22)*15;
  const w2x = Math.sin((x+w1x)*0.025+t*0.4)*8+Math.cos((y+w1y)*0.02-t*0.3)*6;
  const w2y = Math.cos((y+w1y)*0.025-t*0.35)*8+Math.sin((x+w1x)*0.022+t*0.45)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100+Math.cos(t*0.9)*30,80+Math.cos(t*0.4)*50+Math.sin(t*0.7)*20,0.08,2.0],
    [320+Math.cos(t*0.5)*100+Math.sin(t*0.8)*25,160+Math.sin(t*0.7)*50+Math.cos(t*0.6)*25,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [60+Math.sin(t*0.45+3)*60,30+Math.cos(t*0.65+1)*40,0.05,2.8],
    [420+Math.cos(t*0.55+2)*50,210+Math.sin(t*0.75+4)*30,0.11,2.1]
  ];
  let aS=0,iS=0,aS2=0,iS2=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS2+=Math.sin(d*f*1.5-t*sp*0.8+2)*0.5;iS2+=Math.sin(d*f*1.2+t*sp*0.4+3)*0.5;
  }
  const n=src.length,act=aS/n,inh=iS/n,act2=aS2/n,inh2=iS2/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.05+sy*0.01-t*0.6))/3
    +Math.sin((sx+sy)*0.12+t*2.5)*0.15+Math.sin((sx-sy)*0.1-t*2)*0.15
    +Math.sin(Math.sqrt((sx-200)**2+(sy-100)**2)*0.06-t*1.8)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.3
    +Math.sin(dist*0.08-ang*5+t*2)*0.15+Math.sin(dist*0.03+ang*2-t*0.8)*0.1;
  const r1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2=Math.tanh((act2-inh2*0.6+r1*0.4)*2.5);
  const reaction=r1*0.65+r2*0.35;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.22-sy*0.18+t*1.3)*0.3)*1.5)*0.25;
  const contour=Math.pow(Math.abs(Math.sin(reaction*Math.PI*4)),8)*0.15;
  const v=(reaction*0.7+cell*0.2+contour*0.1)*0.5+0.5;
  const pal=[[5,12,52],[10,45,90],[15,85,120],[20,135,135],[60,170,130],[140,195,110],[210,190,80],[230,145,75],[215,95,70],[170,55,75],[100,30,60],[40,15,45],[5,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const energy=Math.abs(reaction),lum=0.85+Math.sin(reaction*Math.PI)*0.15+energy*0.05;
  const edge=Math.abs(reaction)>0.65?1.1+energy*0.1:1.0;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge)|0
  ];
}
